UPDATE incident
SET updated_at = #{updatedAt},
    lock_version = lock_version + 1
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND lock_version = #{expectedVersion}

UPDATE incident
SET status = #{targetStatus},
    resolved_at = #{resolvedAt},
    updated_at = #{updatedAt},
    lock_version = lock_version + 1
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND lock_version = #{expectedVersion}
